CREATE TABLE IF NOT EXISTS employee_contracts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), person_id uuid NOT NULL REFERENCES people_records(id) ON DELETE CASCADE, contract_type text NOT NULL DEFAULT 'full_time', start_date date, end_date date, probation_end_date date, status text NOT NULL DEFAULT 'draft', document_url text, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS employee_compensation (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), person_id uuid NOT NULL REFERENCES people_records(id) ON DELETE CASCADE, effective_from date NOT NULL DEFAULT CURRENT_DATE, salary_amount numeric(14,2), currency text NOT NULL DEFAULT 'NGN', pay_frequency text NOT NULL DEFAULT 'monthly', allowances numeric(14,2) DEFAULT 0, bonus_target numeric(14,2) DEFAULT 0, status text NOT NULL DEFAULT 'active', notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS employee_leave (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), person_id uuid NOT NULL REFERENCES people_records(id) ON DELETE CASCADE, leave_type text NOT NULL, start_date date NOT NULL, end_date date NOT NULL, days numeric(6,2), status text NOT NULL DEFAULT 'pending', reason text, approved_by text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS employee_performance_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), person_id uuid NOT NULL REFERENCES people_records(id) ON DELETE CASCADE, review_period text NOT NULL, reviewer text, rating numeric(4,2), goals text, strengths text, development_areas text, status text NOT NULL DEFAULT 'draft', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS employee_training (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), person_id uuid NOT NULL REFERENCES people_records(id) ON DELETE CASCADE, training_name text NOT NULL, provider text, completed_date date, expiry_date date, certificate_url text, status text NOT NULL DEFAULT 'planned', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS employee_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), person_id uuid NOT NULL REFERENCES people_records(id) ON DELETE CASCADE, asset_type text NOT NULL, asset_tag text, issued_date date, returned_date date, condition_on_issue text, condition_on_return text, status text NOT NULL DEFAULT 'issued', notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS employee_emergency_contacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), person_id uuid NOT NULL REFERENCES people_records(id) ON DELETE CASCADE, full_name text NOT NULL, relationship text, phone text, email text, address text, is_primary boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS employee_exit_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), person_id uuid NOT NULL REFERENCES people_records(id) ON DELETE CASCADE, exit_type text NOT NULL, notice_date date, last_working_date date, reason text, assets_cleared boolean NOT NULL DEFAULT false, access_revoked boolean NOT NULL DEFAULT false, final_payroll_cleared boolean NOT NULL DEFAULT false, exit_interview_complete boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'open', notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_contract_person ON employee_contracts(person_id); CREATE INDEX IF NOT EXISTS idx_comp_person ON employee_compensation(person_id); CREATE INDEX IF NOT EXISTS idx_leave_person ON employee_leave(person_id); CREATE INDEX IF NOT EXISTS idx_perf_person ON employee_performance_reviews(person_id); CREATE INDEX IF NOT EXISTS idx_training_person ON employee_training(person_id); CREATE INDEX IF NOT EXISTS idx_assets_person ON employee_assets(person_id); CREATE INDEX IF NOT EXISTS idx_exit_person ON employee_exit_records(person_id);